 for(const entry of payload.entries){const before=read(entry.file),after=patch(before,entry);if(before===null&&after===null||before!==null&&after!==null&&before.equals(after))continue;changes.push({file:entry.file,beforeHash:before===null?null:hash(before),afterHash:after===null?null:hash(after),after:after===null?null:after.toString('base64')})}
 console.log(changes.length+' widget files would change.');if(dry){console.log('Dry run passed. Nothing written.');process.exit(0)}if(!changes.length){console.log('Source already matches.');process.exit(0)}
 if(fs.existsSync(safe(backup)))throw Error('Backup folder already exists');
